import unicodedata
import re

def normalize_text(text):
    if not text:
        return ""
    # Normalize accents
    nfkd_form = unicodedata.normalize('NFKD', text)
    only_ascii = ''.join([c for c in nfkd_form if not unicodedata.combining(c)])
    # Lowercase
    return only_ascii.lower()

def extract_words(text):
    if not text:
        return set()
    norm = normalize_text(text)
    # Replace underscores and any non-alphanumeric chars with spaces
    cleaned = re.sub(r'[_\W]+', ' ', norm)
    tokens = cleaned.split()
    return set(tokens)

def run(data):
    records = data.get('records', [])
    query = data.get('query', '')
    required_inputs = data.get('required_inputs', [])

    # Filter records: active == true, tested == true, permissions == ["compute"]
    valid_records = []
    for r in records:
        if r.get('active') is True and r.get('tested') is True:
            perms = r.get('permissions', [])
            if perms == ['compute']:
                valid_records.append(r)

    # If there are multiple versions of the same id, handle them or group by id
    # The protocol example suggests keeping the latest or valid active version.
    # Usually records are a list. If multiple records have the same id, we should keep the active/tested ones.
    # Let's map id -> record, or collect all valid records. If duplicates exist, standard practice is taking the latest or valid entry.
    # Looking at the example: "Deactivated version is excluded after a correction", records list can have multiple with same id.

    by_id = {}
    for r in valid_records:
        rid = r['id']
        # Overwrite or collect. Assuming input list has them in order, later overwrites earlier or we take active ones.
        by_id[rid] = r

    index_list = []
    for rid, r in sorted(by_id.items(), key=lambda x: x[0]):
        # Derive terms from id, title, description, input_fields, output_fields
        terms_set = set()

        for w in extract_words(r.get('id', '')):
            terms_set.add(w)
        for w in extract_words(r.get('title', '')):
            terms_set.add(w)
        for w in extract_words(r.get('description', '')):
            terms_set.add(w);
        for inf in r.get('input_fields', []):
            for w in extract_words(inf):
                terms_set.add(w)
        for outf in r.get('output_fields', []):
            for w in extract_words(outf):
                terms_set.add(w)

        sorted_terms = sorted(list(terms_set))
        index_list.append({
            "id": rid,
            "version": r.get('version'),
            "terms": sorted_terms,
            "input_fields": r.get('input_fields', [])
        })

    # Matches computation
    norm_query = normalize_text(query)
    query_tokens = set(re.sub(r'[_\W]+', ' ', norm_query).split())

    matches = []
    for entry in index_list:
        rid = entry['id']
        r_input_fields = entry['input_fields']

        # Check required_inputs (must contain ALL required_inputs)
        has_all_required = True
        for req in required_inputs:
            if req not in r_input_fields:
                has_all_required = False
                break
        if not has_all_required:
            continue

        # Check query
        if not query_tokens:
            matches.append(rid)
        else:
            # Query matches when ANY normalized whole query token occurs in the entry's terms
            matched_query = False
            entry_terms_set = set(entry['terms'])
            for qt in query_tokens:
                if qt in entry_terms_set:
                    matched_query = True
                    break
            if matched_query:
                matches.append(rid)

    # Sort matches by id
    matches = sorted(list(set(matches)))

    return {
        "index": index_list,
        "matches": matches
    }
